SysDataModelXML.SQLScript:
DECLARE @USER VARCHAR(30) = '#LOGIN_USER#'; DECLARE @TAG VARCHAR(200) = '{0}'; DECLARE @PAL VARCHAR(30) = ''; DECLARE @CTR VARCHAR(30) = ''; DECLARE @CTRFLG BIT = 0;
--对标签内容进行处理，兼容原标签 SELECT @TAG = CASE WHEN CHARINDEX('|', @TAG) > 0 THEN LEFT(@TAG, CHARINDEX('|', @TAG) - 1) ELSE @TAG END
SET @CTRFLG = IIF(CHARINDEX('/', @TAG) > 0, 1, 0)
IF @CTRFLG = 0 BEGIN -- 托的处理逻辑 SELECT TOP 1 @PAL = YPALNUM_0 FROM YPALLET WHERE YPALNUM_0 = @TAG;
IF ISNULL(@PAL, '') = '' BEGIN SELECT N'lang:{zh:托号不存在:,en:Pallet No. not found:,de:Paletten-Nr. nicht gefunden:} ' + @TAG 数据检查 RETURN END
IF EXISTS (SELECT TOP 1 * FROM XWSPTHD WHERE XTXT_2 = @TAG AND RPFLG_0<>3) BEGIN SELECT N'lang:{zh:托号已扫描过:,en:Pallet already scanned:,de:Palette bereits gescannt:} ' + @TAG 数据检查 RETURN; END
SELECT MAX(H.ZXLOT_0) 计划号 ,H.YPALNUM_0 托号 ,COUNT(*) 箱数 ,'' 数据检查 ,ISNULL((SELECT COUNT(DISTINCT XTXT_2) FROM XWSPTHD WHERE RPFLG_0<>3 AND USERID_0=@USER), 0) + 1 已扫托数 FROM YZXH H WHERE H.YPALNUM_0 =@TAG GROUP BY H.YPALNUM_0 END ELSE BEGIN -- 箱的处理逻辑 SELECT TOP 1 @CTR = ZXNUM_0 FROM YZXH WHERE ZXLOT_0 + '-' + ZXNUM_0 + '/' = @TAG;
IF ISNULL(@CTR, '') = '' BEGIN SELECT N'lang:{zh:箱号不存在:,en:Carton No. not found:,de:Karton-Nr. nicht gefunden:} ' + @TAG 数据检查 RETURN END
IF EXISTS (SELECT TOP 1 * FROM XWSPTHD WHERE PALNUM_0 + '-' + CTRNUM_0 + '/' = @TAG) BEGIN SELECT N'lang:{zh:箱号已扫描过:,en:Carton already scanned:,de:Karton bereits gescannt:} ' + @TAG 数据检查 RETURN; END
SELECT H.ZXLOT_0 计划号 ,H.ZXNUM_0 箱单号 ,'' 数据检查 ,ISNULL((SELECT COUNT(DISTINCT PALNUM_0+CTRNUM_0) FROM XWSPTHD WHERE RPFLG_0<>3 AND USERID_0=@USER), 0) + 1 已扫箱数 FROM YZXH H WHERE H.ZXLOT_0 + '-' + H.ZXNUM_0 + '/' = @TAG END
